python3 -c 'import json, runpy, subprocess
from pathlib import Path

HOOK = Path("hooks/codex-ux-file-browser-autostart/hook.py")

def repo_root():
    result = subprocess.run(
        ["git", "rev-parse", "--show-toplevel"],
        capture_output=True,
        text=True,
        timeout=2,
        check=False,
    )
    if result.returncode == 0 and result.stdout.strip():
        return Path(result.stdout.strip()).resolve()
    return Path.cwd().resolve()

def plugin_root_for(path):
    for parent in path.parents:
        manifest = parent / ".codex-plugin" / "plugin.json"
        if not manifest.is_file():
            continue
        try:
            payload = json.loads(manifest.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            return None
        if payload.get("name") == "codex-ux":
            return parent
        return None
    return None

def installed_plugin_hooks():
    roots = [
        Path.home() / ".codex" / "plugins" / "codex-ux",
        Path.home() / ".codex" / "plugins" / "cache",
    ]
    hooks = []
    for root in roots:
        if not root.exists():
            continue
        for path in root.glob("**/hooks/codex-ux-file-browser-autostart/hook.py"):
            if plugin_root_for(path) is not None:
                hooks.append(path)
    return sorted(hooks, key=lambda path: path.stat().st_mtime, reverse=True)

root = repo_root()
candidates = [
    root / ".codex" / "codex-ux-file-browser-autostart" / "hook.py",
    root / "plugins" / "codex-ux" / HOOK,
    *installed_plugin_hooks(),
]
for candidate in candidates:
    if candidate.is_file():
        runpy.run_path(str(candidate), run_name="__main__")
        raise SystemExit(0)

print(json.dumps({"continue": True, "suppressOutput": True}))'
